gaeu(){return"\u0420\u04b1\u049b\u0441\u0430\u0442 \u0435\u0442\u0456\u043b\u0433\u0435\u043d \u0435\u04a3 \u0436\u043e\u0493\u0430\u0440\u044b \u043c\u0430\u0441\u0441\u0430\u0441\u044b 3,5 \u0442-\u0434\u0430\u043d \u0430\u0441\u0430\u0442\u044b\u043d \u0436\u04af\u043a \u043a\u04e9\u043b\u0456\u043a\u0442\u0435\u0440\u0456\u043d\u0456\u04a3 \u0436\u04af\u0440\u0443\u0456\u043d\u0435 \u0442\u044b\u0439\u044b\u043c \u0441\u0430\u043b\u0430\u0434\u044b"},
gaev(){return"\u041a\u0435\u0437 \u043a\u0435\u043b\u0433\u0435\u043d \u0442\u04af\u0440\u0434\u0435\u0433\u0456 \u043c\u043e\u0442\u043e\u0446\u0438\u043a\u043b\u0434\u0435\u0440\u0434\u0456\u04a3 \u0436\u04af\u0440\u0443\u0456\u043d\u0435 \u0442\u044b\u0439\u044b\u043c \u0441\u0430\u043b\u0430\u0434\u044b"},
gaew(){return"\u0411\u0430\u0440\u043b\u044b\u049b \u0442\u0440\u0430\u043a\u0442\u043e\u0440\u043b\u0430\u0440 \u043c\u0435\u043d \u04e9\u0437\u0434\u0456\u0433\u0456\u043d\u0435\u043d \u0436\u04af\u0440\u0435\u0442\u0456\u043d \u043c\u0430\u0448\u0438\u043d\u0430\u043b\u0430\u0440\u0434\u044b\u04a3 \u0436\u04af\u0440\u0443\u0456\u043d\u0435 \u0442\u044b\u0439\u044b\u043c \u0441\u0430\u043b\u0430\u0434\u044b"},
gaex(){return"\u0422\u0456\u0440\u043a\u0435\u043c\u0435\u0441\u0456 \u0431\u0430\u0440 \u0436\u04af\u043a \u043a\u04e9\u043b\u0456\u043a\u0442\u0435\u0440\u0456 \u043c\u0435\u043d \u0442\u0440\u0430\u043a\u0442\u043e\u0440\u043b\u0430\u0440\u0434\u044b\u04a3 \u0436\u04af\u0440\u0443\u0456\u043d\u0435, \u0441\u043e\u043d\u0434\u0430\u0439-\u0430\u049b \u0441\u04af\u0439\u0440\u0435\u0442\u0443\u0433\u0435 \u0442\u044b\u0439\u044b\u043c \u0441\u0430\u043b\u0430\u0434\u044b"},
gaej(){return"\u0416\u0430\u044f\u0443 \u0436\u04af\u0440\u0433\u0456\u043d\u0448\u0456\u043b\u0435\u0440 \u043c\u0435\u043d \u0436\u0435\u043a\u0435 \u043c\u043e\u0431\u0438\u043b\u044c\u0434\u0456\u043b\u0456\u043a \u049b\u04b1\u0440\u0430\u043b\u0434\u0430\u0440\u044b\u043d \u043f\u0430\u0439\u0434\u0430\u043b\u0430\u043d\u0443\u0448\u044b\u043b\u0430\u0440\u0434\u044b\u04a3 \u0436\u04af\u0440\u0443\u0456\u043d\u0435 \u0442\u044b\u0439\u044b\u043c \u0441\u0430\u043b\u0430\u0434\u044b"},
gaek(){return"\u0416\u043e\u043b\u0434\u0430\u0440\u0434\u044b\u04a3 \u0435\u04a3 \u0436\u0430\u049b\u044b\u043d \u049b\u0438\u044b\u043b\u044b\u0441\u044b\u043d\u0434\u0430 \u043e\u04a3\u0493\u0430 \u0431\u04b1\u0440\u044b\u043b\u0443\u0493\u0430 \u0442\u044b\u0439\u044b\u043c \u0441\u0430\u043b\u0430\u0434\u044b"},
