gaeo(){return"\u0411\u0430\u044f\u0443 \u0436\u04af\u0440\u0435\u0442\u0456\u043d \u0436\u04d9\u043d\u0435 \u0435\u043a\u0456 \u0434\u04e9\u04a3\u0433\u0435\u043b\u0435\u043a\u0442\u0456 \u043a\u04e9\u043b\u0456\u043a\u0442\u0435\u0440\u0434\u0435\u043d \u0431\u0430\u0441\u049b\u0430 \u043a\u04e9\u043b\u0456\u043a\u0442\u0435\u0440\u0434\u0456 \u0431\u0430\u0441\u044b\u043f \u043e\u0437\u0443\u0493\u0430 \u0442\u044b\u0439\u044b\u043c \u0441\u0430\u043b\u0430\u0434\u044b"},
gaep(){return"\u041c\u0430\u0441\u0441\u0430\u0441\u044b 3,5 \u0442-\u0434\u0430\u043d \u0430\u0441\u0430\u0442\u044b\u043d \u0436\u04af\u043a \u043a\u04e9\u043b\u0456\u043a\u0442\u0435\u0440\u0456\u043d\u0456\u04a3 \u043a\u0435\u0437 \u043a\u0435\u043b\u0433\u0435\u043d \u043a\u04e9\u043b\u0456\u043a\u0442\u0456 \u0431\u0430\u0441\u044b\u043f \u043e\u0437\u0443\u044b\u043d\u0430 \u0442\u044b\u0439\u044b\u043c \u0441\u0430\u043b\u0430\u0434\u044b"},
gaeq(){return"\u0411\u0435\u043b\u0433\u0456\u0434\u0435 \u043a\u04e9\u0440\u0441\u0435\u0442\u0456\u043b\u0433\u0435\u043d \u0436\u044b\u043b\u0434\u0430\u043c\u0434\u044b\u049b\u0442\u0430\u043d \u0430\u0441\u044b\u0440\u0443\u0493\u0430 \u0442\u044b\u0439\u044b\u043c \u0441\u0430\u043b\u0430\u0434\u044b"},
gaer(){return"\u0422\u043e\u049b\u0442\u0430\u0443\u0493\u0430 \u0434\u0430, \u0442\u04b1\u0440\u0430\u049b\u049b\u0430 \u049b\u043e\u044e\u0493\u0430 \u0434\u0430 \u0442\u044b\u0439\u044b\u043c \u0441\u0430\u043b\u0430\u0434\u044b"},
